from gpiozero import PWMOutputDevice, Device
import sys

# GPIO pins driving the PWM channels on the Raspberry Pi
PWM_OUTPUT_PINS = (9, 10, 11, 12, 13)

def build_pwm_devices():
    """Create and return a PWMOutputDevice for each configured pin."""
    # gpiozero manages the PWM frequency internally
    return tuple(PWMOutputDevice(pin_number) for pin_number in PWM_OUTPUT_PINS)

def describe_state(pwm_device):
    """Return a textual description of the current PWM device state."""
    # Report whether the channel is currently active
    return "ON" if pwm_device.value else "OFF"

def main():
    """Drive each PWM output in turn and report its state."""
    pwm_devices = build_pwm_devices()
    try:
        for pwm_device in pwm_devices:
            # Check that the reported value is valid before reporting
            if not isinstance(pwm_device.value, bool):
                raise RuntimeError("invalid PWM value reported")
            print(describe_state(pwm_device))
    except RuntimeError as error:
        # Report any invalid PWM value before exiting
        print("invalid PWM value:", error)
        sys.exit(1)
    except KeyboardInterrupt:
        # Allow a clean stop on user interrupt
        print("stopped by user")
    finally:
        # Release all PWM devices on exit
        for pwm_device in pwm_devices:
            pwm_device.close()

if __name__ == "__main__":
    main()

