import sys

# GPIO pins driving the PWM-capable MOSFET gates on the Raspberry Pi
MOSFET_GPIO_PINS = [12, 13, 18, 19, 22, 23]

def report_state(pwm_device):
    """Print the current PWM duty cycle for a single MOSFET gate."""
    # Report the duty cycle so the operator sees the applied state
    print(pwm_device, "->", round(pwm_device.value, 1), "percent")

def check_reading(pwm_device, min_value, max_value):
    """Reject a PWM device whose duty cycle falls outside the valid range."""
    # Prevent faulty hardware from damaging downstream components
    if not min_value <= pwm_device.value <= max_value:
        print(pwm_device, "-> WARNING: duty cycle out of range")

def main():
    """Drive each MOSFET gate in turn with a 2-second interval."""
    pwm_devices = []
    try:
        # Create a PWMOutputDevice for each configured MOSFET gate
        for gate_pin in MOSFET_GPIO_PINS:
            pwm_devices.append(PWMOutputDevice(gate_pin))
        while True:
            for pwm_device in pwm_devices:
                report_state(pwm_device)
                check_reading(pwm_device, 0.0, 100.0)
            time.sleep(2)
    except KeyboardInterrupt:
        # Allow the operator to stop the controller cleanly
        print("Stopping PWM controller")
    finally:
        # Release every PWM device so the gates are left in a safe state
        for pwm_device in pwm_devices:
            pwm_device.close()

if __name__ == "__main__":
    main()

