from gpiozero import PWMOutputDevice
import sys

SERVO_PINS = {"shoulder": 15, "base": 18}

def report_state(servo_name, servo_device):
    """Print the current PWM state of a servo."""
    # Report the duty cycle so the arm operator sees it
    print("Servo", servo_name, "duty cycle", servo_device.value)

def drive_servo(servo_name, servo_device, angle_value):
    """Move a servo to a target angle and hold it."""
    # Set the duty cycle for the requested angle
    servo_device.value = angle_value
    report_state(servo_name, servo_device)

def main():
    """Drive the robotic arm servos once and exit."""
    # Build the PWMOutputDevice on BCM numbering
    try:
        arm_devices = {name: PWMOutputDevice(pin, initial_value=0)
                      for name, pin in SERVO_PINS.items()}
        for servo_device in arm_devices.values():
            drive_servo(SERVO_PINS[list(SERVO_PINS)[0]], servo_device, 7)
    except KeyError as pin_error:
        # A missing GPIO pin means the wiring is wrong
        print("Servo pin missing:", pin_error)
        sys.exit(1)
    except Exception as runtime_error:
        # Any other failure stops the arm
        print("Servo drive failed:", runtime_error)
        sys.exit(1)
    finally:
        # Release every servo device on exit
        for servo_device in arm_devices.values():
            servo_device.close()

if __name__ == "__main__":
    main()

