# BCM pin assignments for the fan channels
FAN_PINS = {
    "fan1": 4,
    "fan2": 12,
    "fan3": 23,
    "fan4": 24,
    "fan5": 25,
    "fan6": 27,
}

# How often to report each fan's state in seconds
REPORT_INTERVAL = 2

# Keep track of which fans have been set recently
recent_states = {pin: None for pin in FAN_PINS.values()}


def report_fans(output_devices):
    """Print the current state of every configured fan."""
    for name, device in output_devices.items():
        if device.value is not None:
            print(name, "->", "ON" if device.value else "OFF")


def handle_interrupt(signum, frame):
    """Interrupt handler that cleans up the GPIO fan control."""
    print("\nFan control interrupted")
    for device in output_devices.values():
        device.close()
    sys.exit(0)


def main():
    """Configure the fans and report their state repeatedly."""
    output_devices = {}
    try:
        # Create a PWMOutputDevice for each configured fan
        for name, pin in FAN_PINS.items():
            device = PWMOutputDevice(pin)
            output_devices[name] = device
            device.value = True
        signal.signal(signal.SIGINT, handle_interrupt)
        while True:
            report_fans(output_devices)
            time.sleep(REPORT_INTERVAL)
    except Exception as error:
        print("Fan control error:", error)
    finally:
        # Release every fan device on shutdown
        for device in output_devices.values():
            device.close()


