    """Create gpiozero DigitalOutputDevice objects for both pins."""
    # Initialize each digital output device on its BCM pin
    return {pin_name: DigitalOutputDevice(pin_number)
            for pin_name, pin_number in OUTPUT_PINS.items()}


def report_state(output_devices):
    """Print the current state of every digital output device."""
    # Walk the dictionary and announce each output's state
    for device_name, device_value in output_devices.items():
        print("Pin %s -> %s" % (device_name, device_value.value))


