from gpiozero import PWMOutputDevice, CPUTemperature
import time
import sys

# BCM pin assignments for the fan
FAN_PINS = {
    "fan1": 5,   # Fan 1 PWM control
    "fan2": 6,   # Fan 2 PWM control
    "fan3": 13,  # Fan 3 PWM control
    "fan4": 17,  # Fan 4 PWM control
    "fan5": 18,  # Fan 5 PWM control
    "fan6": 22,  # Fan 6 PWM control
    "fan7": 23,  # Fan 7 PWM control
    "fan8": 24,  # Fan 8 PWM control
    "fan9": 27   # Fan 9 PWM control
}

def check_fan_device(device_name):
    """Confirm the requested fan device exists."""
    if device_name not in FAN_PINS:
        raise ValueError(f"unknown fan: {device_name}")

def report_fan_state(fan_device):
    """Print the current PWM state for a fan device."""
    print(fan_device, "->", "ON" if fan_device.value > 0 else "OFF")

def apply_state(fan_device, desired_state):
    """Drive a fan to the requested PWM state."""
    if desired_state == "ON":
        fan_device.value = 100
    elif desired_state == "OFF":
        fan_device.value = 0
    else:
        raise ValueError("unknown fan state")

def main():
    """Continuously report each configured fan's PWM state."""
    fan_devices = {}
    try:
        for fan_name, fan_pin in FAN_PINS.items():
            check_fan_device(fan_name)
            fan_devices[fan_name] = PWMOutputDevice(fan_pin)
        while True:
            for fan_name, fan_device in fan_devices.items():
                report_fan_state(fan_device)
                apply_state(fan_device, "ON")
                time.sleep(1)
                apply_state(fan_device, "OFF")
                time.sleep(1)
            time.sleep(1)
    except ValueError as state_error:
        print("Invalid fan operation:", state_error)
        sys.exit(1)
    except KeyboardInterrupt:
        print("Stopping fans")
    finally:
        # Release every fan device on shutdown
        for fan_device in fan_devices.values():
            fan_device.close()

if __name__ == "__main__":
    main()

