def build_outputs(pin_map):
    """Create a gpiozero output device for each relay pin."""
    # Map each relay name to a configured gpiozero output
    return {name: DigitalOutputDevice(pin, active_high=False, initial_value=False)
            for name, pin in pin_map.items()}


def apply_state(output_devices, target_state):
    """Drive both relays to the requested target state."""
    # Toggle each relay to match the requested state
    for device in output_devices.values():
        device.value = target_state
    return output_devices


if __name__ == "__main__":
    # Configure the relay outputs on the Raspberry Pi
    relay_devices = build_outputs(OUTPUT_PINS)
    try:
        # Set both relays to the requested state and report it
        apply_state(relay_devices, True)
        print("Relay outputs set to ON")
    except Exception as error:
        # Report any failure to set the relay state
        print("Relay control failed:", error)
